contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: call Put with some unlockTime and some value, then attempt Collect for some _am.
    // Assert: if Collect succeeds then Acc(msg.sender).balance decreased by exactly _am and address(c).balance decreased by at least _am;
    // If Collect reverts then we assert that condition (reverted) holds. This is a general property for all inputs.
    function run(uint unlockTime, uint amountPut, uint collectAmt) public payable {
        require(address(this).balance >= amountPut, "insufficient balance for put");

        // Perform Put sending Ether amountPut to c. msg.sender for calls to c is this contract.
        c.Put{value: amountPut}(unlockTime);

        // Read recorded balance for this contract (Acc[address(this)].balance) before Collect
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));

        // Ensure we attempt Collect: call may revert. Capture revert via try/catch.
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read recorded balance and contract balance after Collect attempt
        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // General property: if Collect succeeded (not reverted) then
        //  - the recorded holder balance decreased by exactly collectAmt (unless collectAmt > beforeBalance, but in that case Collect must revert)
        //  - contract Ether balance decreased by at least collectAmt
        // If Collect reverted then we allow state to be unchanged or changed only in ways consistent with revert.
        // We express this as: either reverted is true, or (beforeBalance >= collectAmt && beforeBalance - afterBalance == collectAmt && cBalAfter + collectAmt <= address(this).balance + cBalAfter)
        // To avoid using address(this).balance after external calls, we instead assert: if not reverted then beforeBalance >= collectAmt and beforeBalance - afterBalance == collectAmt.

        assert(reverted || (beforeBalance >= collectAmt && beforeBalance - afterBalance == collectAmt));
    }

    // Allow receiving Ether for funding Put
    receive() external payable {}
}

