    // (1) beforeBalance >= collectAmt
    // (2) beforeBalance - afterBalance == collectAmt
    // (3) address(c).balance decreased by at least collectAmt
    // (4) the holder had beforeBalance >= c.MinSum() and block.timestamp > beforeUnlockTime.
    function run(uint unlockTime, uint amountPut, uint collectAmt) public payable {
        require(address(this).balance >= amountPut, "insufficient balance for put");

        // Perform Put sending Ether amountPut to c. msg.sender for calls to c is this contract.
        c.Put{value: amountPut}(unlockTime);

        // Read recorded holder state before Collect
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Attempt Collect and capture revert
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read holder and contract balance after attempt
        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // If Collect succeeded then: holder had sufficient funds and MinSum and unlock time passed,
        // holder balance decreased exactly by collectAmt, and contract Ether decreased by at least collectAmt.
