        assert(reverted || (
            beforeBalance >= collectAmt &&
            beforeBalance - afterBalance == collectAmt &&
            cBalBefore >= cBalAfter &&
            (cBalBefore - cBalAfter) >= collectAmt &&
            beforeBalance >= c.MinSum() &&
            block.timestamp > beforeUnlockTime
        ));
    }

