contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to attempt to Collect. This contract will act as the holder
    // (msg.sender for calls to c). To allow sending Ether into c for setup, this
    // function is payable and we require this contract has enough balance when needed.
    function run(uint collectAmount, uint putUnlockTime, uint putAmount) public payable {
        // ensure we have funds to call Put if needed
        require(address(this).balance >= putAmount, "need funds to Put");

        // Ensure clean starting point: read recorded holder info before any actions
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // If holder balance is less than desired putAmount, top it up by calling Put
        // Use try/catch to observe whether Put reverted; Put must be a top-level state-changing call
        bool putReverted = false;
        if (beforeBal < putAmount) {
            try c.Put{value: putAmount}(putUnlockTime) {
                putReverted = false;
            } catch {
                putReverted = true;
            }
        }

        // Read mid-state after optional Put
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint cBalMid = address(c).balance;

        // Attempt Collect and record whether it reverts
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-state
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // If Collect succeeded then the following must hold:
        // 1) midBal >= c.MinSum() and midBal >= collectAmount and midUnlock < block.timestamp
        //    (these are the contract's preconditions for allowing Collect), and
        // 2) the recorded balance decreased exactly by collectAmount, and
        // 3) the contract's Ether balance did not increase (it must have decreased by at least collectAmount).
        // If Collect reverted, we don't assert anything further.

        // Read MinSum and current block timestamp via observable effects: MinSum is public, block.timestamp used directly.
        uint minSum = c.MinSum();

        assert(collectReverted || (
            // preconditions were satisfied at mid-state
            midBal >= minSum && midBal >= collectAmount && midUnlock < block.timestamp &&
            // recorded balance decreased exactly by collectAmount
            afterBal + collectAmount == midBal &&
            // contract balance decreased by at least collectAmount
            cBalAfter + collectAmount <= cBalMid
        ));
    }

    // Allow this test contract to receive Ether
    receive() external payable {}
}

