contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit some ether via Put, then try to Collect the same or smaller amount
    // Parameters:
    //  - unlockTime: set for Put (if <= block.timestamp inside Put it becomes block.timestamp)
    //  - amount: the amount to send with Put (and that we will later attempt to Collect)
    //  - collectAmount: the amount to request in Collect
    function run(uint unlockTime, uint amount, uint collectAmount) public payable {
        require(address(this).balance >= amount, "insufficient test balance for Put");
        // Deposit 'amount' into c under this contract's address
        c.Put{value: amount}(unlockTime);

        // Read recorded balance before Collect via the public getter Acc(address).balance
        (uint accUnlockTimeBefore, uint accBalanceBefore) = c.Acc(address(this));
        // Ensure we only attempt Collect when recorded balance is at least collectAmount
        // The property we will assert only applies when accBalanceBefore >= collectAmount and collectAmount >= c.MinSum()
        // so we don't try to prove impossible invariants for invalid Collect attempts.
        // We still perform the Collect call and capture whether it reverted.
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        (uint accUnlockTimeAfter, uint accBalanceAfter) = c.Acc(address(this));
        uint contractBalanceAfter = address(c).balance;

        // If Collect did not revert and preconditions for Collect were met (balance>=MinSum, balance>=collectAmount, now>unlockTime)
        // then recorded balance must have decreased by collectAmount and contract balance must have decreased by collectAmount.
        // We fetch MinSum and current block.timestamp via available calls/values. MinSum is public.
        uint minSum = c.MinSum();

        bool precondsMet = (accBalanceBefore >= minSum) && (accBalanceBefore >= collectAmount) && (block.timestamp > accUnlockTimeBefore);

        // General rule: if Collect did not revert and preconditions were satisfied, then both recorded balance and contract balance decreased by exactly collectAmount.
        assert(!reverted && precondsMet ? (accBalanceBefore == accBalanceAfter + collectAmount && (address(c).balance + collectAmount) == contractBalanceAfter + collectAmount ? false : true) : true);
    }

    // receive to accept Ether if the C contract sends funds back
    receive() external payable {}
}

