contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking params: unlock time and amount to send to Put
    function run(uint _unlockTime, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        // read balance for this contract's holder before
        (uint beforeUnlock, uint beforeBalance) = getAcc(msg.sender);

        // perform Put by calling fallback when amount==0 to cover that path, else call Put
        if (amount == 0) {
            // call fallback which forwards to Put(0)
            // fallback is external payable
            (bool s,) = address(c).call{value: 0}("0x");
            // we don't require success because fallback will always call Put and may revert only on reentrancy
            // but we will record whether it reverted by s
        } else {
            // call Put with provided unlock time and value
            c.Put{value: amount}(_unlockTime);
        }

        // read balance after
        (uint afterUnlock, uint afterBalance) = getAcc(msg.sender);

        // The general invariant: afterBalance >= beforeBalance and the increase equals exactly amount
        // Note: address(c).balance also increases by amount for non-reverting calls, but we only assert relation of recorded balances.
        assert(afterBalance >= beforeBalance && afterBalance - beforeBalance == amount);
    }

    // helper to call the public getter Acc(address) which returns Holder (unlockTime, balance)
    function getAcc(address adr) internal returns (uint, uint) {
        // The compiler-generated getter for public mapping returns (uint unlockTime, uint balance)
        // Call it as external function on c
        (uint u, uint b) = c.Acc(adr);
        return (u, b);
    }

    receive() external payable {}
}

